CREATE TABLE clarity.recovery_scans (`recovery_id` Int64, `hit_id` Int64, `scan_id` Int64, `hit_type` String, `kit_id` Int32, `ocr` String, `geo` Point DEFAULT (0, 0), `scanned_at` DateTime64(6), `_peerdb_synced_at` DateTime64(9), `_peerdb_version` UInt64, `_peerdb_is_deleted` UInt8, INDEX idx_recovery_id recovery_id TYPE minmax GRANULARITY 1, INDEX idx_scan_id scan_id TYPE minmax GRANULARITY 1, INDEX idx_hit_type hit_type TYPE set(3) GRANULARITY 1, INDEX idx_scanned_at scanned_at TYPE minmax GRANULARITY 1, INDEX idx_peerdb_is_deleted _peerdb_is_deleted TYPE minmax GRANULARITY 4) ENGINE = ReplacingMergeTree(_peerdb_version) ORDER BY (recovery_id, scan_id) SETTINGS index_granularity = 8192;
CREATE TABLE clarity.sc_positions (`id` Int32, `kit_mapping` String, `gl` String, `timestamp_utc` DateTime, `timestamp_local` DateTime, `geo` Point, `speed` Float32, `heading` Float32, `ingested_at` DateTime64(3) MATERIALIZED now64(3), PROJECTION proj_kit_mapping_lc (SELECT * ORDER BY lower(kit_mapping), timestamp_utc)) ENGINE = MergeTree() ORDER BY (kit_mapping, timestamp_utc) TTL timestamp_utc + toIntervalDay(120) SETTINGS index_granularity = 8192;
CREATE TABLE clarity.scan_report (`kit_id` Int32, `org_id` Int32, `name` String, `one_hour` UInt64, `four_hour` UInt64, `one_day` UInt64, `seven_day` UInt64, `thirty_day` UInt64, `one_year` UInt64, INDEX idx_org_id org_id TYPE set(100) GRANULARITY 4) ENGINE = MergeTree() ORDER BY (org_id, kit_id) SETTINGS index_granularity = 8192;
CREATE TABLE clarity.scan_report_hourly (`org_id` Int32, `kit_id` Int32, `scan_hour` DateTime, `scan_count` AggregateFunction(uniqExact, Int64), `_peerdb_synced_at` DateTime64(6) DEFAULT now64(6), INDEX idx_org_id org_id TYPE set(100) GRANULARITY 4, INDEX idx_scan_hour scan_hour TYPE minmax GRANULARITY 1) ENGINE = AggregatingMergeTree() PARTITION BY toYYYYMM(scan_hour) ORDER BY (org_id, kit_id, scan_hour) SETTINGS index_granularity = 8192;
CREATE TABLE clarity.scans_cold (`id` Int64, `kit_id` Int32, `ocr` String, `us_state` String, `camera_name` String, `guid` UUID, `scanned_at` DateTime64(6), `created_at` DateTime64(6), `lng` Float64 DEFAULT 0, `lat` Float64 DEFAULT 0, `geo` Point DEFAULT (0, 0), `kit_name` String DEFAULT '', `org_id` Int32 DEFAULT 0, `disposition` Nullable(String) DEFAULT NULL, `address` Nullable(String) DEFAULT NULL, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_version` UInt64, `_peerdb_is_deleted` UInt8 DEFAULT 0, INDEX idx_lng lng TYPE minmax GRANULARITY 4, INDEX idx_lat lat TYPE minmax GRANULARITY 4, INDEX idx_disposition disposition TYPE set(20) GRANULARITY 4, INDEX idx_org_id org_id TYPE set(100) GRANULARITY 4, INDEX idx_id id TYPE minmax GRANULARITY 1, INDEX idx_id_bloom id TYPE bloom_filter(0.01) GRANULARITY 1, INDEX idx_ocr ocr TYPE bloom_filter(0.001) GRANULARITY 1) ENGINE = ReplacingMergeTree(_version, _peerdb_is_deleted) PARTITION BY toYYYYMM(scanned_at) ORDER BY (org_id, scanned_at, kit_id, id) SETTINGS index_granularity = 8192;
CREATE TABLE clarity.scans_hot (`id` Int64, `kit_id` Int32, `ocr` String, `us_state` String, `camera_name` String, `guid` UUID, `scanned_at` DateTime64(6), `created_at` DateTime64(6), `lng` Float64 DEFAULT 0, `lat` Float64 DEFAULT 0, `geo` Point DEFAULT (0, 0), `kit_name` String DEFAULT '', `org_id` Int32 DEFAULT 0, `disposition` Nullable(String) DEFAULT NULL, `address` Nullable(String) DEFAULT NULL, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_version` UInt64, `_peerdb_is_deleted` UInt8 DEFAULT 0, INDEX idx_ocr ocr TYPE ngrambf_v1(3, 256, 2, 0) GRANULARITY 4, INDEX idx_lng lng TYPE minmax GRANULARITY 4, INDEX idx_lat lat TYPE minmax GRANULARITY 4, INDEX idx_disposition disposition TYPE set(20) GRANULARITY 4, INDEX idx_org_id org_id TYPE set(100) GRANULARITY 4, INDEX idx_id id TYPE minmax GRANULARITY 1, INDEX idx_id_bloom id TYPE bloom_filter(0.01) GRANULARITY 1) ENGINE = ReplacingMergeTree(_version, _peerdb_is_deleted) PARTITION BY toYYYYMMDD(scanned_at) ORDER BY (org_id, scanned_at, kit_id, id) TTL toDateTime(scanned_at) + toIntervalDay(90) SETTINGS index_granularity = 8192;
CREATE TABLE clarity.scout_open_addresses (`org_id` Int32, `is_staged` Bool, `hotlist_id` Int64, `address_id` Int64, `geo` Point, `refreshed_at` DateTime) ENGINE = MergeTree() ORDER BY (org_id, is_staged, hotlist_id, address_id) SETTINGS index_granularity = 8192;
CREATE TABLE clarity.tmp_recovery_lookup (`plate` String, `org_id` Int32, `recovery_id` Int64, `repo_date` Date, `scan_start` DateTime, `scan_end` DateTime, `geo` Point) ENGINE = MergeTree() ORDER BY (plate, org_id) SETTINGS index_granularity = 8192;
CREATE TABLE zod.address_geo_wkt (`id` Int64, `geo_wkt` Nullable(String)) ENGINE = MergeTree() ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.aggregate_kit_camera_name (`kit_id` Int32, `camera_name` String) ENGINE = ReplacingMergeTree() ORDER BY (kit_id, camera_name) SETTINGS index_granularity = 8192;
CREATE TABLE zod.aggregate_scan_count_h (`hour` DateTime, `camera_id` Int64, `scan_count` SimpleAggregateFunction(sum, UInt64)) ENGINE = SummingMergeTree() PARTITION BY toYYYYMM(hour) ORDER BY (camera_id, hour) SETTINGS index_granularity = 8192;
CREATE TABLE zod.hotlist_json_denormalized (`hotlist_id` Int64, `case_number` Nullable(String), `vehicle_color` Nullable(String), `description` Nullable(String), `entering_agency` Nullable(String), `expires_at` Nullable(String), `plate_type` Nullable(String), `file_type_decode` Nullable(String), `title_number` Nullable(String), `plate_expired_at` Nullable(String), `vin` Nullable(String), `vehicle_type` Nullable(String), `vehicle_year` Nullable(String), `vehicle_model` Nullable(String), `vehicle_make` Nullable(String), `remote_order_id` Nullable(String), `plate` Nullable(String), `state` Nullable(String), `file_type` Nullable(Int32), `source` Nullable(String), `reason` Nullable(String), `location` Nullable(String), `branch_id` Nullable(Int64), `updated_at` Nullable(DateTime), `_peerdb_synced_at` DateTime, `_peerdb_is_deleted` Int8, `_peerdb_version` Int64, INDEX idx_peerdb_synced_at _peerdb_synced_at TYPE minmax GRANULARITY 1, INDEX idx_hotlist_id_synced (hotlist_id, _peerdb_synced_at) TYPE minmax GRANULARITY 1) ENGINE = ReplacingMergeTree(_peerdb_version) ORDER BY hotlist_id SETTINGS index_granularity = 8192;
CREATE TABLE zod.kit_last_scan (`org_id` Int64, `org_name` String, `kit_id` Int32, `kit_name` String, `last_scan` DateTime64(6)) ENGINE = ReplacingMergeTree(last_scan) ORDER BY (org_id, kit_id) SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_address (`id` Int64, `house_number` Nullable(String), `road` Nullable(String), `city` Nullable(String), `state` Nullable(String), `postcode` Nullable(String), `geo` Nullable(String), `orig` String, `type_id` Nullable(Int32), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_api_keys (`id` Int32, `org_id` Nullable(Int32), `key` Nullable(String), `description` Nullable(String), `active` Nullable(Bool), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_approval_list (`id` Int64, `agent_org_id` Nullable(Int32), `staging_org_id` Nullable(Int32), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_authorized_staging_orgs (`id` Int32, `staging_org_id` Int32, `authorized_org_id` Int32, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_billing_events (`id` Int64, `api_key_id` Int32, `success` Bool, `event_type` String, `additional` String, `ts` Int64, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_blacklist_plates (`id` Int32, `plate` String, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_blacklist_repo_client (`id` Int32, `repo_org_id` Int32, `client_org_id` Int32, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_hits (`id` Int64, `hotlist_id` Int64, `scan_id` Int64, `hit_type` String, `created_at` DateTime64(6), `kit_id` Int32, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64, INDEX idx_peerdb_synced_at _peerdb_synced_at TYPE minmax GRANULARITY 1, INDEX idx_created_at created_at TYPE minmax GRANULARITY 1, INDEX idx_scan_id scan_id TYPE minmax GRANULARITY 1, INDEX idx_hit_type hit_type TYPE set(10) GRANULARITY 4) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id TTL _peerdb_synced_at + toIntervalDay(1) WHERE _peerdb_is_deleted = 1 SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_hits_meta (`id` Int64, `properties` String, `created_at` DateTime64(6), `updated_at` Nullable(DateTime64(6)), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_hotlist (`id` Int64, `integration_id` Int32, `remote_order_id` Nullable(String), `status` Int32, `org_id` Int32, `client_org_id` Int32, `lienholder_org_id` Nullable(Int32), `order_type` Int32, `is_staged` Bool, `plate` String, `us_state` String, `vin` String, `vehicle_year` String, `vehicle_make` String, `vehicle_model` String, `lookback_days` Int32, `created_at` DateTime64(6), `updated_at` DateTime64(6), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_hotlist_address (`id` Int32, `hotlist_id` Int64, `address_id` Int64, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_hotlist_expiration (`id` Int64, `hotlist_id` Int64, `expiration_date` DateTime64(6), `created_at` Nullable(DateTime64(6)), `updated_at` Nullable(DateTime64(6)), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_hotlist_import_log (`id` Int64, `start_time` DateTime64(6), `end_time` Nullable(DateTime64(6)), `successful` Bool, `integration_id` Int64, `import_setting_id` Int64, `rows_added` Nullable(Int32), `rows_updated` Nullable(Int32), `rows_removed` Nullable(Int32), `file_removed` Bool, `count_db_rows_before_import` Int32, `count_file_rows` Int32, `org_id` Int64, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_hotlist_json (`hotlist_id` Int64, `json` String, `created_at` Nullable(DateTime64(6)), `updated_at` Nullable(DateTime64(6)), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY hotlist_id ORDER BY hotlist_id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_hotlist_meta (`id` Int64, `hotlist_id` Nullable(Int64), `order_date` Date32, `repo_date` Nullable(Date32), `close_date` Nullable(Date32), `monthly_payments` Nullable(Decimal(10, 2)), `balance_on_account` Nullable(Decimal(10, 2)), `amount_past_due` Nullable(Decimal(10, 2)), `additional_info` Nullable(String), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_hotlist_plate_log (`id` Int64, `hotlist_id` Int64, `old_plate` String, `old_state` String, `new_plate` String, `new_state` String, `created_at` DateTime64(6), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_hotlist_status_log (`id` Int64, `hotlist_id` Int64, `old_status` Int32, `new_status` Int32, `created_at` DateTime64(6), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_integrations (`id` Int32, `name` String, `status` String, `batch_id` Nullable(Int64), `mapping_id` Int32, `mapping_type` Nullable(String), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_kits (`id` Int32, `org_id` Int32, `kit_mapping` String, `kit_type` Int32, `name` String, `text_phone` Nullable(String), `fixed_latitude` Nullable(Float64), `fixed_longitude` Nullable(Float64), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64, `email` Nullable(String), `signing_public_key` Nullable(String)) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_org_meta (`id` Int64, `properties` String, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_orgs (`id` Int32, `name` String, `address_id` Nullable(Int64), `type` Int32, `rdn_id` Nullable(String), `rdn_api_key` Nullable(String), `irepo_id` Nullable(String), `enable_genetech_hotlist` Bool, `enable_matrix_hotlist` Bool, `silent_hit_generation` Bool, `ls_id` Nullable(String), `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_scans (`id` Int64, `ocr` String, `us_state` String, `geo` String, `kit_id` Int32, `is_visible` Bool, `scanned_at` DateTime64(6), `created_at` DateTime64(6), `camera_name` String, `guid` UUID, `meta` String, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64, INDEX idx_peerdb_synced_at _peerdb_synced_at TYPE minmax GRANULARITY 1, INDEX idx_is_visible is_visible TYPE minmax GRANULARITY 1, INDEX idx_kit_id kit_id TYPE minmax GRANULARITY 1) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY (id, scanned_at) ORDER BY (id, scanned_at) SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_scans_metadata (`scan_id` Int64, `meta` String, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64, INDEX idx_peerdb_synced_at _peerdb_synced_at TYPE minmax GRANULARITY 1) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY scan_id ORDER BY scan_id TTL _peerdb_synced_at + toIntervalDay(1) WHERE _peerdb_is_deleted = 1 SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_timezones (`gid` Int32, `tzid` Nullable(String), `geom` Nullable(String), `original_geom` String, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY gid ORDER BY gid SETTINGS index_granularity = 8192;
CREATE TABLE zod.public_user_orgs (`id` Int32, `user_id` Int32, `org_id` Int32, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) PRIMARY KEY id ORDER BY id SETTINGS index_granularity = 8192;
CREATE TABLE zod.scan_counts_daily (`org_id` Int32, `scan_date` Date, `scan_count` SimpleAggregateFunction(sum, UInt64), `min_scanned_at` SimpleAggregateFunction(min, DateTime64(6)), `max_scanned_at` SimpleAggregateFunction(max, DateTime64(6))) ENGINE = SummingMergeTree() PARTITION BY toYYYYMM(scan_date) ORDER BY (org_id, scan_date) SETTINGS index_granularity = 8192;
CREATE TABLE zod.scan_lag_5min (`kit_id` Int32, `time_bucket` DateTime, `scan_count` UInt64, `avg_lag_sec` Float64, `median_lag_sec` Float64, `min_lag_sec` Int64, `max_lag_sec` Int64, `stddev_lag_sec` Float64) ENGINE = ReplacingMergeTree() ORDER BY (kit_id, time_bucket) TTL time_bucket + toIntervalDay(30) SETTINGS index_granularity = 8192;
CREATE TABLE zod.scan_ttl_compliance (`org_id` Int32, `org_name` String, `ttl_days` Int32, `cutoff_date` Date, `oldest_scan` Date, `newest_scan` Date, `total_scans` UInt64, `scans_past_ttl` UInt64, `status` String, `updated_at` DateTime DEFAULT now()) ENGINE = ReplacingMergeTree(updated_at) ORDER BY org_id SETTINGS index_granularity = 8192;
CREATE TABLE zod.scans_metadata_extracted (`scan_id` Int64, `kit_id` Nullable(Int32), `vehicle_type` Nullable(String), `vehicle_color` Nullable(String), `vehicle_make` Nullable(String), `is_not_plate` Bool, `ml_plate_state` Nullable(String), `address` Nullable(String), `simple_address` Nullable(String), `disposition` Nullable(String), `is_daytime` Bool, `_peerdb_synced_at` DateTime64(9) DEFAULT now64(), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64, INDEX idx_vehicle_type vehicle_type TYPE set(100) GRANULARITY 4, INDEX idx_vehicle_color vehicle_color TYPE set(200) GRANULARITY 4, INDEX idx_vehicle_make vehicle_make TYPE bloom_filter(0.01) GRANULARITY 4, INDEX idx_ml_plate_state ml_plate_state TYPE bloom_filter(0.01) GRANULARITY 4, INDEX idx_is_daytime is_daytime TYPE minmax GRANULARITY 4, INDEX idx_is_not_plate is_not_plate TYPE minmax GRANULARITY 4, INDEX idx_disposition disposition TYPE set(20) GRANULARITY 4, INDEX idx_peerdb_synced_at _peerdb_synced_at TYPE minmax GRANULARITY 1) ENGINE = ReplacingMergeTree(_peerdb_version, _peerdb_is_deleted) ORDER BY scan_id TTL _peerdb_synced_at + toIntervalDay(1) WHERE _peerdb_is_deleted = 1 SETTINGS index_granularity = 8192;
CREATE TABLE zod.scans_out_of_policy_data (`scan_id` Int64, `guid` UUID, `kit_id` Int32, `scanned_at` DateTime64(6), `created_at` DateTime64(6), `org_id` Int32, `org_name` String, `ttl_days` Int32, `age_days` Int32, `refreshed_at` DateTime DEFAULT now()) ENGINE = ReplacingMergeTree(refreshed_at) PRIMARY KEY (org_id, kit_id, scan_id) ORDER BY (org_id, kit_id, scan_id, scanned_at) SETTINGS index_granularity = 8192;
CREATE TABLE zod.timezones_geo (`gid` Int32, `tzid` Nullable(String), `geom` MultiPolygon) ENGINE = MergeTree() ORDER BY gid SETTINGS index_granularity = 8192;

-- ===========================================
-- VIEWS (13)
-- ===========================================
CREATE VIEW clarity.billing_claim_events_v AS SELECT id, org_id, agent_org_id, vin, hotlist_id, event_type, success, is_internal, event_date, ts, api_key_id, _peerdb_synced_at, _version FROM clarity.billing_claim_events FINAL WHERE _peerdb_is_deleted = 0;
CREATE VIEW clarity.client_days_to_repo_all (`hour_timestamp` DateTime, `org_id` UInt32, `client_org_id` UInt32, `branch_id` UInt32, `sum_days_to_repo_all` Int64, `count_repos_all` UInt64, `sum_days_to_repo_involuntary` Int64, `count_repos_involuntary` UInt64, `sum_days_to_repo_voluntary` Int64, `count_repos_voluntary` UInt64, `sum_days_to_repo_investigate` Int64, `count_repos_investigate` UInt64, `sum_days_to_repo_impound` Int64, `count_repos_impound` UInt64, `sum_days_to_repo_lpr_staging` Int64, `count_repos_lpr_staging` UInt64, `sum_days_to_repo_unknown` Int64, `count_repos_unknown` UInt64) AS SELECT hour_timestamp, org_id, client_org_id, branch_id, sum(days_to_repo) AS sum_days_to_repo_all, count() AS count_repos_all, sumIf(days_to_repo, order_type = 1) AS sum_days_to_repo_involuntary, countIf(order_type = 1) AS count_repos_involuntary, sumIf(days_to_repo, order_type = 2) AS sum_days_to_repo_voluntary, countIf(order_type = 2) AS count_repos_voluntary, sumIf(days_to_repo, order_type = 3) AS sum_days_to_repo_investigate, countIf(order_type = 3) AS count_repos_investigate, sumIf(days_to_repo, order_type = 10) AS sum_days_to_repo_impound, countIf(order_type = 10) AS count_repos_impound, sumIf(days_to_repo, order_type = 88) AS sum_days_to_repo_lpr_staging, countIf(order_type = 88) AS count_repos_lpr_staging, sumIf(days_to_repo, order_type = 99) AS sum_days_to_repo_unknown, countIf(order_type = 99) AS count_repos_unknown FROM clarity.client_days_to_repo FINAL WHERE _peerdb_is_deleted = 0 GROUP BY hour_timestamp, org_id, client_org_id, branch_id;
CREATE VIEW clarity.integrations (`id` Int32, `name` String, `status` String, `batch_id` Nullable(Int64), `mapping_id` Int32, `mapping_type` Nullable(String), `_peerdb_synced_at` DateTime64(9), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) AS SELECT * FROM zod.public_integrations FINAL WHERE id IN (1, 2, 6, 8, 9, 10, 44, 1482);
CREATE VIEW clarity.lpr_assists (`recovery_id` Int64) AS SELECT DISTINCT recovery_id FROM clarity.recovery_scans WHERE _peerdb_is_deleted = 0;
CREATE VIEW clarity.orgs (`id` Int32, `name` String, `address_id` Nullable(Int64), `type` Int32, `rdn_id` Nullable(String), `rdn_api_key` Nullable(String), `irepo_id` Nullable(String), `enable_genetech_hotlist` Bool, `enable_matrix_hotlist` Bool, `silent_hit_generation` Bool, `ls_id` Nullable(String), `_peerdb_synced_at` DateTime64(9), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) AS SELECT * FROM zod.public_orgs WHERE type IN (1, 2);
CREATE VIEW clarity.scans_metadata (`scan_id` Int64, `kit_id` Nullable(Int32), `vehicle_type` Nullable(String), `vehicle_color` Nullable(String), `vehicle_make` Nullable(String), `is_not_plate` Bool, `ml_plate_state` Nullable(String), `address` Nullable(String), `simple_address` Nullable(String), `disposition` Nullable(String), `is_daytime` Bool, `_peerdb_synced_at` DateTime64(9), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) AS SELECT * FROM zod.scans_metadata_extracted WHERE kit_id IN (SELECT k.id FROM zod.public_kits AS k INNER JOIN zod.public_orgs AS o ON k.org_id = o.id WHERE o.type = 1);
CREATE VIEW zod.hotlist_json_latest (`hotlist_id` Int64, `json` String) AS SELECT hotlist_id, argMax(json, _peerdb_version) AS json FROM zod.public_hotlist_json WHERE _peerdb_is_deleted = 0 GROUP BY hotlist_id;
CREATE VIEW zod.hotlist_latest (`id` Int64, `org_id` Int32, `integration_id` Int32, `remote_order_id` Nullable(String), `client_org_id` Int32, `lienholder_org_id` Nullable(Int32), `status` Int32, `order_type` Int32, `is_staged` Bool, `plate` String, `us_state` String, `vin` String, `vehicle_year` String, `vehicle_make` String, `vehicle_model` String, `lookback_days` Int32, `created_at` DateTime64(6), `updated_at` DateTime64(6)) AS SELECT id, argMax(org_id, _peerdb_version) AS org_id, argMax(integration_id, _peerdb_version) AS integration_id, argMax(remote_order_id, _peerdb_version) AS remote_order_id, argMax(client_org_id, _peerdb_version) AS client_org_id, argMax(lienholder_org_id, _peerdb_version) AS lienholder_org_id, argMax(status, _peerdb_version) AS status, argMax(order_type, _peerdb_version) AS order_type, argMax(is_staged, _peerdb_version) AS is_staged, argMax(plate, _peerdb_version) AS plate, argMax(us_state, _peerdb_version) AS us_state, argMax(vin, _peerdb_version) AS vin, argMax(vehicle_year, _peerdb_version) AS vehicle_year, argMax(vehicle_make, _peerdb_version) AS vehicle_make, argMax(vehicle_model, _peerdb_version) AS vehicle_model, argMax(lookback_days, _peerdb_version) AS lookback_days, argMax(created_at, _peerdb_version) AS created_at, argMax(updated_at, _peerdb_version) AS updated_at FROM zod.public_hotlist WHERE _peerdb_is_deleted = 0 GROUP BY id;
CREATE VIEW zod.hotlist_meta_latest (`hotlist_id` Nullable(Int64), `repo_date` Nullable(Date32), `order_date` Date32) AS SELECT hotlist_id, argMax(repo_date, _peerdb_version) AS repo_date, argMax(order_date, _peerdb_version) AS order_date FROM zod.public_hotlist_meta WHERE _peerdb_is_deleted = 0 GROUP BY hotlist_id;
CREATE VIEW zod.kits_latest (`id` Int32, `org_id` Int32) AS SELECT id, argMax(org_id, _peerdb_version) AS org_id FROM zod.public_kits WHERE _peerdb_is_deleted = 0 GROUP BY id;
CREATE VIEW zod.public_org_meta_latest (`id` Int64, `properties` String) AS SELECT id, argMax(properties, _peerdb_version) AS properties FROM zod.public_org_meta WHERE _peerdb_is_deleted = 0 GROUP BY id;
CREATE VIEW zod.public_orgs_latest (`id` Int32, `name` String, `address_id` Nullable(Int64), `type` Int32, `rdn_id` Nullable(String), `rdn_api_key` Nullable(String), `irepo_id` Nullable(String), `enable_genetech_hotlist` Bool, `enable_matrix_hotlist` Bool, `silent_hit_generation` Bool, `ls_id` Nullable(String)) AS SELECT id, argMax(name, _peerdb_version) AS name, argMax(address_id, _peerdb_version) AS address_id, argMax(type, _peerdb_version) AS type, argMax(rdn_id, _peerdb_version) AS rdn_id, argMax(rdn_api_key, _peerdb_version) AS rdn_api_key, argMax(irepo_id, _peerdb_version) AS irepo_id, argMax(enable_genetech_hotlist, _peerdb_version) AS enable_genetech_hotlist, argMax(enable_matrix_hotlist, _peerdb_version) AS enable_matrix_hotlist, argMax(silent_hit_generation, _peerdb_version) AS silent_hit_generation, argMax(ls_id, _peerdb_version) AS ls_id FROM zod.public_orgs WHERE _peerdb_is_deleted = 0 GROUP BY id;
CREATE VIEW zod.scan_lag_anomalies (`kit_id` Int32, `time_bucket` DateTime, `scan_count` UInt64, `avg_lag_sec` Float64, `median_lag_sec` Float64, `max_lag_sec` Int64, `kit_rolling_avg` Float64, `kit_stddev` Float64, `deviation_from_avg` Float64, `status` String) AS WITH kit_averages AS (SELECT kit_id, avg(avg_lag_sec) AS kit_avg_lag, stddevPop(avg_lag_sec) AS kit_stddev_lag FROM zod.scan_lag_5min WHERE time_bucket >= (now() - toIntervalDay(7)) GROUP BY kit_id) SELECT b.kit_id, b.time_bucket, b.scan_count, round(b.avg_lag_sec, 1) AS avg_lag_sec, round(b.median_lag_sec, 1) AS median_lag_sec, b.max_lag_sec, round(ka.kit_avg_lag, 1) AS kit_rolling_avg, round(ka.kit_stddev_lag, 1) AS kit_stddev, round(b.avg_lag_sec - ka.kit_avg_lag, 1) AS deviation_from_avg, multiIf((ka.kit_stddev_lag > 0) AND (b.avg_lag_sec > (ka.kit_avg_lag + (2 * ka.kit_stddev_lag))), 'ANOMALY', b.avg_lag_sec > (ka.kit_avg_lag * 1.5), 'ELEVATED', 'NORMAL') AS status FROM zod.scan_lag_5min AS b INNER JOIN kit_averages AS ka ON b.kit_id = ka.kit_id WHERE b.time_bucket >= (now() - toIntervalHour(24));

