CREATE MATERIALIZED VIEW clarity.billing_claim_events_mv REFRESH EVERY 1 HOUR APPEND TO clarity.billing_claim_events DEFINER = default SQL SECURITY DEFINER AS WITH fact_watermark AS (SELECT coalesce(max(_peerdb_synced_at), toDateTime64('1970-01-01', 9)) - toIntervalSecond(30) AS ts FROM clarity.billing_claim_events), api_key_watermark AS (SELECT coalesce(max(_peerdb_api_key_synced_at), toDateTime64('1970-01-01', 9)) AS ts FROM clarity.billing_claim_events), changed_api_key_ids AS (SELECT DISTINCT id FROM zod.public_api_keys FINAL WHERE _peerdb_is_deleted = 0 AND _peerdb_synced_at > (SELECT ts FROM api_key_watermark)), orgs AS (SELECT id, lower(replaceRegexpAll(coalesce(name, ''), '[^a-zA-Z0-9]', '')) AS n FROM zod.public_orgs FINAL WHERE _peerdb_is_deleted = 0), claims AS (SELECT be.id AS id, ifNull(ak.org_id, 0) AS org_id, toInt32(JSONExtractInt(be.additional, 'claimed_by_org_id')) AS agent_org_id, upper(trimBoth(JSONExtractString(be.additional, 'vin'))) AS vin, JSONExtractInt(be.additional, 'hotlist_id') AS hotlist_id, be.event_type AS event_type, be.success AS success, toDate(fromUnixTimestamp(be.ts), 'UTC') AS event_date, be.ts AS ts, be.api_key_id AS api_key_id, be._peerdb_synced_at AS _peerdb_synced_at, ak._peerdb_synced_at AS _peerdb_api_key_synced_at, toUInt64(greatest(be._peerdb_version, coalesce(ak._peerdb_version, 0))) AS _version, be._peerdb_is_deleted AS _peerdb_is_deleted FROM zod.public_billing_events AS be INNER JOIN (SELECT id, org_id, _peerdb_synced_at, _peerdb_version FROM zod.public_api_keys FINAL WHERE _peerdb_is_deleted = 0) AS ak ON ak.id = be.api_key_id WHERE be.event_type = 'case-claim' AND be._peerdb_is_deleted = 0 AND (be._peerdb_synced_at >= (SELECT ts FROM fact_watermark) OR (ak.id IN (SELECT id FROM changed_api_key_ids) AND toDate(fromUnixTimestamp(be.ts), 'UTC') >= today() - 8))) SELECT c.id AS id, c.org_id AS org_id, c.agent_org_id AS agent_org_id, c.vin AS vin, c.hotlist_id AS hotlist_id, c.event_type AS event_type, c.success AS success, if(position(coalesce(fo.n, ''), 'insightlpr') > 0 OR position(coalesce(ao.n, ''), 'insightlpr') > 0, 1, 0) AS is_internal, c.event_date AS event_date, c.ts AS ts, c.api_key_id AS api_key_id, c._peerdb_synced_at AS _peerdb_synced_at, c._peerdb_api_key_synced_at AS _peerdb_api_key_synced_at, c._version AS _version, c._peerdb_is_deleted AS _peerdb_is_deleted FROM claims AS c LEFT JOIN orgs AS fo ON fo.id = c.org_id LEFT JOIN orgs AS ao ON ao.id = c.agent_org_id;
CREATE MATERIALIZED VIEW clarity.hotlist_incremental_mv REFRESH EVERY 1 MINUTE APPEND TO clarity.hotlist (`id` Int64, `org_id` Int32, `integration_id` Int32, `remote_order_id` Nullable(String), `client_org_id` Int32, `client_org_name` Nullable(String), `lienholder_org_id` Nullable(Int32), `lienholder_org_name` Nullable(String), `status` Int32, `order_type` Int32, `is_staged` Bool, `plate` String, `us_state` String, `vin` String, `vehicle_year` String, `vehicle_make` String, `vehicle_model` String, `lookback_days` Int32, `created_at` DateTime64(6), `updated_at` DateTime64(6), `branch_id` Nullable(Int64), `_peerdb_synced_at` DateTime64(9), `_peerdb_hj_synced_at` DateTime64(9), `_peerdb_hm_synced_at` DateTime64(9), `repo_date` Nullable(Date), `order_date` Nullable(Date), `close_date` Nullable(Date), `_version` UInt64, `_peerdb_is_deleted` UInt8, `first_open_at` Nullable(DateTime64(6)), `first_hold_at` Nullable(DateTime64(6)), `first_repossessed_at` Nullable(DateTime64(6)), `first_declined_at` Nullable(DateTime64(6)), `first_closed_at` Nullable(DateTime64(6)), `first_invalid_at` Nullable(DateTime64(6)), `_peerdb_hsl_synced_at` DateTime64(9)) DEFINER = default SQL SECURITY DEFINER AS WITH hotlist_watermark AS (SELECT coalesce(max(_peerdb_synced_at), toDateTime64('1970-01-01', 9)) - toIntervalSecond(30) AS ts FROM clarity.hotlist), hj_watermark AS (SELECT greatest(coalesce(max(_peerdb_hj_synced_at), toDateTime64('1970-01-01', 9)) - toIntervalSecond(30), (SELECT ts FROM hotlist_watermark) - toIntervalHour(1)) AS ts FROM clarity.hotlist), hm_watermark AS (SELECT greatest(coalesce(max(_peerdb_hm_synced_at), toDateTime64('1970-01-01', 9)) - toIntervalSecond(30), (SELECT ts FROM hotlist_watermark) - toIntervalHour(1)) AS ts FROM clarity.hotlist), hsl_watermark AS (SELECT greatest(coalesce(max(_peerdb_hsl_synced_at), toDateTime64('1970-01-01', 9)) - toIntervalSecond(30), (SELECT ts FROM hotlist_watermark) - toIntervalHour(1)) AS ts FROM clarity.hotlist), changed_hotlist_ids AS (SELECT id FROM zod.public_hotlist WHERE _peerdb_synced_at >= (SELECT ts FROM hotlist_watermark) UNION DISTINCT SELECT hotlist_id AS id FROM zod.hotlist_json_denormalized WHERE _peerdb_synced_at >= (SELECT ts FROM hj_watermark) UNION DISTINCT SELECT assumeNotNull(hotlist_id) AS id FROM zod.public_hotlist_meta WHERE _peerdb_synced_at >= (SELECT ts FROM hm_watermark) UNION DISTINCT SELECT hotlist_id AS id FROM zod.public_hotlist_status_log WHERE _peerdb_synced_at >= (SELECT ts FROM hsl_watermark)), h_deduped AS (SELECT id, argMax(org_id, _peerdb_version) AS org_id, argMax(integration_id, _peerdb_version) AS integration_id, argMax(remote_order_id, _peerdb_version) AS remote_order_id, argMax(client_org_id, _peerdb_version) AS client_org_id, argMax(lienholder_org_id, _peerdb_version) AS lienholder_org_id, argMax(status, _peerdb_version) AS status, argMax(order_type, _peerdb_version) AS order_type, argMax(is_staged, _peerdb_version) AS is_staged, argMax(plate, _peerdb_version) AS plate, argMax(us_state, _peerdb_version) AS us_state, argMax(vin, _peerdb_version) AS vin, argMax(vehicle_year, _peerdb_version) AS vehicle_year, argMax(vehicle_make, _peerdb_version) AS vehicle_make, argMax(vehicle_model, _peerdb_version) AS vehicle_model, argMax(lookback_days, _peerdb_version) AS lookback_days, argMax(created_at, _peerdb_version) AS created_at, argMax(updated_at, _peerdb_version) AS updated_at, argMax(_peerdb_synced_at, _peerdb_version) AS _peerdb_synced_at, max(_peerdb_version) AS max_version, argMax(_peerdb_is_deleted, _peerdb_version) AS _peerdb_is_deleted FROM zod.public_hotlist WHERE id IN (SELECT id FROM changed_hotlist_ids) GROUP BY id), hj_deduped AS (SELECT hotlist_id, argMax(branch_id, _peerdb_version) AS branch_id, argMax(_peerdb_synced_at, _peerdb_version) AS _peerdb_synced_at, max(_peerdb_version) AS max_version, argMax(_peerdb_is_deleted, _peerdb_version) AS _peerdb_is_deleted FROM zod.hotlist_json_denormalized WHERE hotlist_id IN (SELECT id FROM changed_hotlist_ids) GROUP BY hotlist_id), hm_deduped AS (SELECT assumeNotNull(hotlist_id) AS hotlist_id, argMax(repo_date, _peerdb_version) AS repo_date, argMax(order_date, _peerdb_version) AS order_date, argMax(close_date, _peerdb_version) AS close_date, argMax(_peerdb_synced_at, _peerdb_version) AS _peerdb_synced_at, max(_peerdb_version) AS max_version, argMax(_peerdb_is_deleted, _peerdb_version) AS _peerdb_is_deleted FROM zod.public_hotlist_meta WHERE hotlist_id IN (SELECT id FROM changed_hotlist_ids) GROUP BY hotlist_id), hsl_deduped AS (SELECT hotlist_id, minIf(toNullable(created_at), new_status = 1) AS first_open_at, minIf(toNullable(created_at), new_status = 2) AS first_hold_at, minIf(toNullable(created_at), new_status = 3) AS first_repossessed_at, minIf(toNullable(created_at), new_status = 4) AS first_declined_at, minIf(toNullable(created_at), new_status = 5) AS first_closed_at, minIf(toNullable(created_at), new_status = 99) AS first_invalid_at, max(_peerdb_synced_at) AS _peerdb_synced_at, max(_peerdb_version) AS max_version FROM zod.public_hotlist_status_log WHERE hotlist_id IN (SELECT id FROM changed_hotlist_ids) AND _peerdb_is_deleted = 0 GROUP BY hotlist_id) SELECT h.id AS id, h.org_id AS org_id, h.integration_id AS integration_id, h.remote_order_id AS remote_order_id, h.client_org_id AS client_org_id, co.name AS client_org_name, h.lienholder_org_id AS lienholder_org_id, lo.name AS lienholder_org_name, h.status AS status, h.order_type AS order_type, h.is_staged AS is_staged, h.plate AS plate, h.us_state AS us_state, h.vin AS vin, h.vehicle_year AS vehicle_year, h.vehicle_make AS vehicle_make, h.vehicle_model AS vehicle_model, h.lookback_days AS lookback_days, h.created_at AS created_at, h.updated_at AS updated_at, hj.branch_id AS branch_id, h._peerdb_synced_at AS _peerdb_synced_at, coalesce(hj._peerdb_synced_at, h._peerdb_synced_at) AS _peerdb_hj_synced_at, coalesce(hm._peerdb_synced_at, h._peerdb_synced_at) AS _peerdb_hm_synced_at, hm.repo_date AS repo_date, hm.order_date AS order_date, hm.close_date AS close_date, greatest(toUInt64(h.max_version), toUInt64(ifNull(hj.max_version, 0)), toUInt64(ifNull(hm.max_version, 0)), toUInt64(ifNull(hsl.max_version, 0))) AS _version, h._peerdb_is_deleted AS _peerdb_is_deleted, hsl.first_open_at AS first_open_at, hsl.first_hold_at AS first_hold_at, hsl.first_repossessed_at AS first_repossessed_at, hsl.first_declined_at AS first_declined_at, hsl.first_closed_at AS first_closed_at, hsl.first_invalid_at AS first_invalid_at, ifNull(hsl._peerdb_synced_at, toDateTime64('1970-01-01', 9)) AS _peerdb_hsl_synced_at FROM h_deduped AS h LEFT JOIN hj_deduped AS hj ON hj.hotlist_id = h.id AND hj._peerdb_is_deleted = 0 LEFT JOIN hm_deduped AS hm ON hm.hotlist_id = h.id AND hm._peerdb_is_deleted = 0 LEFT JOIN hsl_deduped AS hsl ON hsl.hotlist_id = h.id LEFT JOIN zod.public_orgs_latest AS co ON co.id = h.client_org_id LEFT JOIN zod.public_orgs_latest AS lo ON lo.id = h.lienholder_org_id WHERE h.org_id IN (SELECT id FROM clarity.orgs FINAL) AND h._peerdb_is_deleted = 0;
CREATE MATERIALIZED VIEW clarity.hotlist_status_transitions_mv REFRESH EVERY 15 MINUTE APPEND TO clarity.hotlist_status_transitions ( `id` Int64, `org_id` Int32, `hotlist_id` Int64, `created_at` DateTime64(6), `old_status` Int32, `new_status` Int32, `_peerdb_synced_at` DateTime64(9) ) DEFINER = default SQL SECURITY DEFINER AS WITH watermark AS ( SELECT coalesce(maxOrNull(_peerdb_synced_at), now64(9)) - toIntervalHour(24) AS ts FROM clarity.hotlist_status_transitions ), log_tail AS ( SELECT id, hotlist_id, created_at, old_status, new_status, _peerdb_synced_at FROM zod.public_hotlist_status_log WHERE (_peerdb_synced_at >= ( SELECT ts FROM watermark )) AND (_peerdb_is_deleted = 0) ), hotlist_org AS ( SELECT id, argMax(org_id, _peerdb_version) AS org_id FROM zod.public_hotlist WHERE id IN ( SELECT hotlist_id FROM log_tail ) GROUP BY id ), candidates AS ( SELECT l.id AS id, o.org_id AS org_id, l.hotlist_id AS hotlist_id, l.created_at AS created_at, l.old_status AS old_status, l.new_status AS new_status, l._peerdb_synced_at AS _peerdb_synced_at FROM log_tail AS l INNER JOIN hotlist_org AS o ON o.id = l.hotlist_id WHERE o.org_id IN ( SELECT id FROM clarity.orgs FINAL ) ) SELECT id, org_id, hotlist_id, created_at, old_status, new_status, _peerdb_synced_at FROM candidates WHERE id NOT IN ( SELECT id FROM clarity.hotlist_status_transitions WHERE created_at >= ( SELECT minOrNull(created_at) FROM log_tail ) ) SETTINGS max_memory_usage = 8000000000;
CREATE MATERIALIZED VIEW zod.eric_test (`id` Int64, `integration_id` Int32, `remote_order_id` Nullable(String), `status` Int32) ENGINE = ReplacingMergeTree(status) ORDER BY id SETTINGS index_granularity = 8192 AS SELECT public_hotlist.id AS id, integration_id, remote_order_id, public_hotlist.status AS status FROM zod.public_hotlist LEFT JOIN zod.public_orgs ON (org_id = public_orgs.id) AND (enable_genetech_hotlist = 1) WHERE (integration_id IN (1, 2, 5, 6, 8, 9, 10, 44, 1482)) AND (((public_orgs.id IS NULL) AND (is_staged = 1)) OR ((public_orgs.id IS NOT NULL) AND (is_staged = 0)));
CREATE MATERIALIZED VIEW zod.hotlist_json_denormalized_mv TO zod.hotlist_json_denormalized (`hotlist_id` Int64, `case_number` String, `vehicle_color` String, `description` String, `entering_agency` String, `expires_at` String, `plate_type` String, `file_type_decode` String, `title_number` String, `plate_expired_at` String, `vin` String, `vehicle_type` String, `vehicle_year` String, `vehicle_model` String, `vehicle_make` String, `remote_order_id` String, `plate` String, `state` String, `file_type` Int64, `source` String, `reason` String, `location` String, `branch_id` Int64, `updated_at` Nullable(DateTime64(6)), `_peerdb_synced_at` DateTime64(9), `_peerdb_is_deleted` UInt8, `_peerdb_version` UInt64) AS SELECT hotlist_id, JSONExtractString(json, 'case_number') AS case_number, JSONExtractString(json, 'vehicle_color') AS vehicle_color, JSONExtractString(json, 'description') AS description, JSONExtractString(json, 'entering_agency') AS entering_agency, JSONExtractString(json, 'expires_at') AS expires_at, JSONExtractString(json, 'plate_type') AS plate_type, JSONExtractString(json, 'file_type_decode') AS file_type_decode, JSONExtractString(json, 'title_number') AS title_number, JSONExtractString(json, 'plate_expired_at') AS plate_expired_at, JSONExtractString(json, 'vin') AS vin, JSONExtractString(json, 'vehicle_type') AS vehicle_type, JSONExtractString(json, 'vehicle_year') AS vehicle_year, JSONExtractString(json, 'vehicle_model') AS vehicle_model, JSONExtractString(json, 'vehicle_make') AS vehicle_make, JSONExtractString(json, 'remote_order_id') AS remote_order_id, JSONExtractString(json, 'plate') AS plate, JSONExtractString(json, 'state') AS state, JSONExtractInt(json, 'file_type') AS file_type, JSONExtractString(json, 'source') AS source, JSONExtractString(json, 'reason') AS reason, JSONExtractString(json, 'location') AS location, JSONExtractInt(json, 'branch_id') AS branch_id, updated_at, _peerdb_synced_at, _peerdb_is_deleted, _peerdb_version FROM zod.public_hotlist_json;
CREATE MATERIALIZED VIEW zod.kit_last_scan_mv TO zod.kit_last_scan (`org_id` Int32, `org_name` String, `kit_id` Int32, `kit_name` String, `last_scan` DateTime64(6)) AS SELECT k.org_id, o.name AS org_name, s.kit_id, k.name AS kit_name, s.scanned_at AS last_scan FROM zod.public_scans AS s INNER JOIN zod.public_kits AS k ON s.kit_id = k.id INNER JOIN zod.public_orgs AS o ON k.org_id = o.id WHERE (s._peerdb_is_deleted = 0) AND (k._peerdb_is_deleted = 0) AND (o._peerdb_is_deleted = 0);
CREATE MATERIALIZED VIEW zod.scan_lag_5min_mv TO zod.scan_lag_5min (`kit_id` Int32, `time_bucket` DateTime, `scan_count` UInt64, `avg_lag_sec` Float64, `median_lag_sec` Float64, `min_lag_sec` Int64, `max_lag_sec` Int64, `stddev_lag_sec` Float64) AS SELECT kit_id, toStartOfFiveMinutes(created_at) AS time_bucket, count() AS scan_count, avg(dateDiff('second', scanned_at, created_at)) AS avg_lag_sec, median(dateDiff('second', scanned_at, created_at)) AS median_lag_sec, min(dateDiff('second', scanned_at, created_at)) AS min_lag_sec, max(dateDiff('second', scanned_at, created_at)) AS max_lag_sec, stddevPop(dateDiff('second', scanned_at, created_at)) AS stddev_lag_sec FROM zod.public_scans WHERE _peerdb_is_deleted = 0 GROUP BY kit_id, time_bucket;
